sealed class CoreException(message: String): kotlin.Exception(message) {
        
        class Database(message: String) : CoreException(message)
        
        class Validation(message: String) : CoreException(message)
        
        class NotFound(message: String) : CoreException(message)
        
        class Migration(message: String) : CoreException(message)
        
        class LockException(message: String) : CoreException(message)
        
        class Serialization(message: String) : CoreException(message)
        
        class UuidParse(message: String) : CoreException(message)
        
        class TimeParse(message: String) : CoreException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        
            return when(buf.getInt()) {
            1 -> CoreException.Database(FfiConverterString.read(buf))
            2 -> CoreException.Validation(FfiConverterString.read(buf))
            3 -> CoreException.NotFound(FfiConverterString.read(buf))
            4 -> CoreException.Migration(FfiConverterString.read(buf))
            5 -> CoreException.LockException(FfiConverterString.read(buf))
            6 -> CoreException.Serialization(FfiConverterString.read(buf))
            7 -> CoreException.UuidParse(FfiConverterString.read(buf))
            8 -> CoreException.TimeParse(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: CoreException): ULong {
        return 4UL
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.Database -> {
                buf.putInt(1)
                Unit
            }
            is CoreException.Validation -> {
                buf.putInt(2)
                Unit
            }
            is CoreException.NotFound -> {
                buf.putInt(3)
                Unit
            }
            is CoreException.Migration -> {
                buf.putInt(4)
                Unit
            }
            is CoreException.LockException -> {
                buf.putInt(5)
                Unit
            }
            is CoreException.Serialization -> {
                buf.putInt(6)
                Unit
            }
            is CoreException.UuidParse -> {
                buf.putInt(7)
                Unit
            }
            is CoreException.TimeParse -> {
                buf.putInt(8)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




